import{_ as o,C as s,c as r,o as c,a3 as a,G as n}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Scan adjustments","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/barcode/scan-adjustments.md","filePath":"master/supply-chain/inventories/barcode/scan-adjustments.md","lastUpdated":1791902625000}'),i={name:"master/supply-chain/inventories/barcode/scan-adjustments.md"};function l(d,t,u,h,p,m){const e=s("ImagePopup");return c(),r("div",null,[t[0]||(t[0]=a('<h1 id="scan-adjustments" tabindex="-1">Scan adjustments <a class="header-anchor" href="#scan-adjustments" aria-label="Permalink to &quot;Scan adjustments&quot;">​</a></h1><p>Count stock with a scanner. Scan a location, then scan each product or lot on its shelf. The app builds the counted quantity for you. When you are happy, apply it.</p><blockquote><p><strong>In simple words:</strong> Scan the shelf, count the items, then apply.</p></blockquote><p>Open <code>Barcode → Barcode App → Inventory Adjustments</code>. The page subtitle is <strong>Count stock by location, product, or lot</strong>. It works on the same data as <a href="./../adjustments/inventory-adjustments.html">Inventory adjustments</a>.</p><h2 id="the-list" tabindex="-1">The list <a class="header-anchor" href="#the-list" aria-label="Permalink to &quot;The list&quot;">​</a></h2><p>Each card is one stock row. It shows the location (for example <code>WH/Stock</code>), the product, the lot if any, and a progress such as <strong>0 / 110 Units</strong> (counted over on hand). A quick button, for example <strong>+110</strong>, sets the count to the on hand quantity. Check and clear icons apply or discard the count.</p>',6)),n(e,{src:"/images1/inventory/bc_adjustments.png",alt:"Barcode Inventory Adjustments list with Camping Hammock in WH/Stock showing 0 / 110 Units"}),t[1]||(t[1]=a('<h2 id="count-by-scanning" tabindex="-1">Count by scanning <a class="header-anchor" href="#count-by-scanning" aria-label="Permalink to &quot;Count by scanning&quot;">​</a></h2><ol><li>Type or scan in <strong>Scan or search by location, product, lot, serial...</strong> and click <strong>Open</strong>.</li><li>Scan a location. A message says <strong>Scanning location WH/Stock. Scan more products here or scan another location.</strong></li><li>Scan each product or lot. Each scan raises its counted quantity.</li><li>Click <strong>Clear filters</strong> to remove the location filter.</li></ol><h2 id="edit-a-count" tabindex="-1">Edit a count <a class="header-anchor" href="#edit-a-count" aria-label="Permalink to &quot;Edit a count&quot;">​</a></h2><p>Click the pencil icon. The <strong>Adjustment details</strong> screen says <strong>Review stock details and update the counted quantity.</strong> It shows <strong>Location</strong>, <strong>Lot/Serial</strong>, <strong>On hand</strong> and <strong>Counted</strong>.</p>',4)),n(e,{src:"/images1/inventory/bc_adjustment_details.png",alt:"Adjustment details screen with On hand 110 and Counted 108"}),t[2]||(t[2]=a('<p>Use the buttons to set the count to 0, subtract 1, add 1 or fill the remaining quantity. Click <strong>Confirm</strong> to save, or <strong>Discard</strong>. A message says <strong>Inventory count saved.</strong></p><h2 id="apply-or-clear" tabindex="-1">Apply or clear <a class="header-anchor" href="#apply-or-clear" aria-label="Permalink to &quot;Apply or clear&quot;">​</a></h2><p>Click the check icon to apply. A message says <strong>Inventory adjustment applied.</strong> The stock is corrected. Click the clear icon to remove the count. A message says <strong>Inventory count cleared.</strong></p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Barcode app</a></li><li><a href="./scan-operations.html">Scan operations</a></li><li><a href="./../adjustments/inventory-adjustments.html">Inventory adjustments</a></li></ul>',5))])}c